 for key,q in included.items():expressions.append("SELECT '"+key+"'::text AS key,coalesce(json_agg(v),'[]'::json)AS rows FROM("+q.rstrip(';')+")sub(v)")
 combined="SELECT json_object_agg(key,rows)FROM("+' UNION ALL '.join(expressions)+")u;"
 actual=sql(combined)
 assert hashlib.sha256(path.read_bytes()).hexdigest()==ENV_SHA
 receipt={'status':'PASS_READONLY_QA_DRAIN_SNAPSHOT','atUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'state':x.state,'sourceHead':head,'oldPidPresent':old.exists(),'qaPort3003Listeners':listener_count,'qaSockets':qa_sockets,'qaSocketsPid':observed_pid,'qaSocketsStartTicks':observed_start,'snapshotIsolation':'REPEATABLE READ READ ONLY, ROLLBACK','sourceDatabase':'melamedia','sourceRole':'melamedia_app','aggregates':actual,'absentRelations':absent,'querySha256':{k:hashlib.sha256(v.encode()).hexdigest()for k,v in included.items()},'providerCalls':0,'dataWrites':0,'rawCustomerOrProviderReferencesExported':False}
 print(json.dumps(receipt))
